// NVMe value index — record JAH-GPCS-NVMESSD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"seq_read_mbs": 7000, "endurance_tbw": 600};
var value = (m.seq_read_mbs/1000*(m.endurance_tbw**0.5));
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-NVMESSD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-NVMESSD-000001|' + value.toFixed(2) + ' value index');

